from __future__ import annotations

import html


def build_visual_measurement_guides_html(bike_type: str) -> str:
    kind = (bike_type or "Gravel").lower()
    is_drop = kind in {"gravel", "road", "szosa", "tt", "triathlon"}
    handlebar_label = "baranek / klamkomanetka" if is_drop else "prosta kierownica / grip"
    handlebar_svg = """
      <path d="M95 84 C145 70 196 72 235 88" fill="none" stroke="#dbe8f2" stroke-width="12" stroke-linecap="round"/>
      <path d="M218 86 C252 94 268 122 254 153 C245 172 226 183 209 174" fill="none" stroke="#dbe8f2" stroke-width="11" stroke-linecap="round"/>
      <path d="M224 82 L244 63 L260 72" fill="none" stroke="#dbe8f2" stroke-width="7" stroke-linecap="round"/>
      <circle cx="238" cy="73" r="9" fill="#67e4b5" stroke="#fff" stroke-width="3"/>
      <text x="238" y="45" fill="#67e4b5" text-anchor="middle" font-weight="800">PUNKT H</text>
      <text x="238" y="207" fill="#9fb5c7" text-anchor="middle">środek miejsca podparcia dłoni</text>
      <path d="M275 151 l15 15 m0-15 l-15 15" stroke="#ff6f86" stroke-width="5"/>
      <text x="300" y="173" fill="#ff8da0">nie koniec baranka</text>
    """ if is_drop else """
      <path d="M68 104 C126 96 200 96 273 104" fill="none" stroke="#dbe8f2" stroke-width="13" stroke-linecap="round"/>
      <rect x="203" y="91" width="68" height="26" rx="12" fill="#64788c"/>
      <circle cx="235" cy="104" r="9" fill="#67e4b5" stroke="#fff" stroke-width="3"/>
      <text x="235" y="72" fill="#67e4b5" text-anchor="middle" font-weight="800">PUNKT H</text>
      <text x="235" y="145" fill="#9fb5c7" text-anchor="middle">środek gripa / miejsca chwytu</text>
      <path d="M282 91 l15 15 m0-15 l-15 15" stroke="#ff6f86" stroke-width="5"/>
      <text x="305" y="110" fill="#ff8da0">nie sam koniec kierownicy</text>
    """

    return f'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#07131e;color:#eef7ff;font-family:Segoe UI,Arial,sans-serif}}
    .top{{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px}}button{{background:#173047;color:white;border:1px solid #4c708d;border-radius:10px;padding:10px 13px;font-weight:750;cursor:pointer}}button:hover,button.active{{background:#286080;border-color:#67e4b5}}
    .card{{display:none;background:linear-gradient(145deg,#102536,#0b1925);border:1px solid #385a73;border-radius:18px;padding:15px}}.card.active{{display:block}}
    .grid{{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(290px,.85fr);gap:16px;align-items:stretch}}
    .drawing{{background:radial-gradient(circle at 50% 40%,#17384f,#08141f 72%);border:1px solid #35536b;border-radius:16px;padding:8px;min-height:390px}}
    svg{{width:100%;height:100%;display:block}}.steps{{background:#102131;border:1px solid #35536b;border-radius:16px;padding:15px}}h2,h3{{margin:0 0 10px}}.step{{display:flex;gap:10px;margin:11px 0;line-height:1.38}}.n{{flex:0 0 28px;height:28px;border-radius:50%;background:#67e4b5;color:#06231a;font-weight:900;text-align:center;line-height:28px}}
    .ok{{border-left:4px solid #67e4b5;background:#102b28;padding:10px;border-radius:8px;margin-top:12px}}.bad{{border-left:4px solid #ff6f86;background:#311c28;padding:10px;border-radius:8px;margin-top:10px}}.tag{{display:inline-block;padding:4px 8px;border-radius:999px;background:#19384e;color:#bfe1f6;font-size:12px;margin-bottom:8px}}
    @media(max-width:800px){{.grid{{grid-template-columns:1fr}}.drawing{{min-height:320px}}}}
    </style></head><body>
    <div class="top" id="nav"></div>
    <section class="card active" data-id="handlebar"><div class="grid"><div class="drawing"><svg viewBox="0 0 420 260">
      <text x="20" y="28" fill="#eef7ff" font-size="18" font-weight="800">Punkt chwytu — {html.escape(handlebar_label)}</text>
      <path d="M45 118 L92 103" stroke="#7f96aa" stroke-width="12" stroke-linecap="round"/><circle cx="47" cy="118" r="8" fill="#78baff"/>{handlebar_svg}
      <line x1="238" y1="73" x2="238" y2="225" stroke="#ffd166" stroke-width="3" stroke-dasharray="7 6"/><text x="238" y="245" fill="#ffd166" text-anchor="middle" font-weight="800">do tego pionu mierz reach/drop</text>
    </svg></div><div class="steps"><span class="tag">Automatycznie dobrano: {html.escape(bike_type)}</span><h3>Gdzie kończyć pomiar?</h3>
      <div class="step"><span class="n">1</span><div>Połóż dłoń w naturalnym miejscu chwytu używanym podczas spokojnej jazdy.</div></div><div class="step"><span class="n">2</span><div>Zaznacz środek miejsca podparcia dłoni — to punkt <b>H</b>.</div></div><div class="step"><span class="n">3</span><div>Do punktu H mierz odległość od S75 lub od pionu przechodzącego przez suport.</div></div>
      <div class="ok"><b>Dobrze:</b> środek klamkomanetki albo środek gripa.</div><div class="bad"><b>Błąd:</b> pomiar do końca baranka, końca kierownicy lub śruby obejmy.</div>
    </div></div></section>
    <section class="card" data-id="saddle"><div class="grid"><div class="drawing"><svg viewBox="0 0 420 260"><text x="20" y="28" fill="#eef7ff" font-size="18" font-weight="800">Punkt S75 na siodle</text><path d="M72 116 C115 75 272 74 345 111 C303 136 151 145 72 116Z" fill="#e8eef4" stroke="#8ba0b2" stroke-width="3"/><path d="M132 105 C175 91 230 91 274 105" fill="none" stroke="#516779" stroke-width="10" stroke-linecap="round"/><line x1="223" y1="70" x2="223" y2="174" stroke="#ffd166" stroke-width="3" stroke-dasharray="7 5"/><line x1="185" y1="151" x2="261" y2="151" stroke="#67e4b5" stroke-width="5"/><circle cx="223" cy="118" r="10" fill="#67e4b5" stroke="#fff" stroke-width="3"/><text x="223" y="202" fill="#67e4b5" text-anchor="middle" font-weight="900">S75 — środek przekroju 75 mm</text><path d="M340 112 l15 15 m0-15 l-15 15" stroke="#ff6f86" stroke-width="5"/><text x="332" y="153" fill="#ff8da0" text-anchor="end">nie czubek</text></svg></div><div class="steps"><h3>Jak znaleźć S75?</h3><div class="step"><span class="n">1</span><div>Mierz szerokość siodła poprzecznie.</div></div><div class="step"><span class="n">2</span><div>Znajdź przekrój, w którym siodło ma około <b>75 mm szerokości</b>.</div></div><div class="step"><span class="n">3</span><div>Zaznacz środek siodła w tym przekroju.</div></div><div class="ok"><b>Dobrze:</b> stały punkt geometryczny.</div><div class="bad"><b>Błąd:</b> środek długości, środek otworu albo sam nos.</div></div></div></section>
    <section class="card" data-id="bb"><div class="grid"><div class="drawing"><svg viewBox="0 0 420 260"><text x="20" y="28" fill="#eef7ff" font-size="18" font-weight="800">Środek suportu BB</text><circle cx="195" cy="130" r="61" fill="#152b3c" stroke="#8da2b5" stroke-width="10"/><circle cx="195" cy="130" r="25" fill="#78baff" stroke="#fff" stroke-width="4"/><line x1="195" y1="130" x2="318" y2="83" stroke="#d9e3ec" stroke-width="13" stroke-linecap="round"/><circle cx="318" cy="83" r="17" fill="#67e4b5"/><line x1="195" y1="49" x2="195" y2="211" stroke="#ffd166" stroke-width="3" stroke-dasharray="7 5"/><line x1="114" y1="130" x2="276" y2="130" stroke="#ffd166" stroke-width="3" stroke-dasharray="7 5"/><text x="195" y="238" fill="#ffd166" text-anchor="middle" font-weight="900">BB = dokładny środek osi korby</text></svg></div><div class="steps"><h3>Skąd rozpocząć pomiar?</h3><div class="step"><span class="n">1</span><div>Znajdź środek śruby lub osi korby.</div></div><div class="step"><span class="n">2</span><div>Przyłóż początek metrówki dokładnie do środka osi.</div></div><div class="step"><span class="n">3</span><div>Od BB mierz wysokość siodła, długość korby i front-center.</div></div><div class="bad"><b>Błąd:</b> dolna krawędź mufy lub śruba blatu.</div></div></div></section>
    <section class="card" data-id="saddleheight"><div class="grid"><div class="drawing"><svg viewBox="0 0 420 260"><text x="20" y="28" fill="#eef7ff" font-size="18" font-weight="800">Wysokość siodła po osi sztycy</text><circle cx="120" cy="215" r="13" fill="#78baff" stroke="#fff" stroke-width="3"/><line x1="120" y1="215" x2="245" y2="69" stroke="#7f96aa" stroke-width="15" stroke-linecap="round"/><line x1="92" y1="222" x2="261" y2="52" stroke="#ffd166" stroke-width="5"/><path d="M88 222 l14 0 l-8-13Z" fill="#ffd166"/><path d="M262 48 l-14 2 l8 12Z" fill="#ffd166"/><line x1="211" y1="65" x2="300" y2="63" stroke="#eef4f8" stroke-width="13" stroke-linecap="round"/><circle cx="245" cy="69" r="9" fill="#67e4b5" stroke="#fff" stroke-width="3"/><text x="250" y="235" fill="#ffd166" text-anchor="middle" font-weight="900">BB → góra siodła, wzdłuż osi</text></svg></div><div class="steps"><h3>M1 — wysokość siodła</h3><div class="step"><span class="n">1</span><div>Punkt startowy to środek BB.</div></div><div class="step"><span class="n">2</span><div>Poprowadź metrówkę <b>wzdłuż osi rury podsiodłowej i sztycy</b>.</div></div><div class="step"><span class="n">3</span><div>Zakończ na górnej powierzchni siodła w osi sztycy.</div></div><div class="bad"><b>Błąd:</b> pomiar pionowo do podłoża albo do nosa.</div></div></div></section>
    <section class="card" data-id="stem"><div class="grid"><div class="drawing"><svg viewBox="0 0 420 260"><text x="20" y="28" fill="#eef7ff" font-size="18" font-weight="800">Długość mostka</text><circle cx="105" cy="135" r="20" fill="#78baff" stroke="#fff" stroke-width="3"/><circle cx="312" cy="92" r="20" fill="#67e4b5" stroke="#fff" stroke-width="3"/><path d="M105 135 L312 92" stroke="#dce6ee" stroke-width="22" stroke-linecap="round"/><line x1="105" y1="135" x2="312" y2="92" stroke="#ffd166" stroke-width="4"/><text x="105" y="175" fill="#78baff" text-anchor="middle" font-weight="800">środek sterów</text><text x="312" y="132" fill="#67e4b5" text-anchor="middle" font-weight="800">oś kierownicy</text></svg></div><div class="steps"><h3>Mostek — od środka do środka</h3><div class="step"><span class="n">1</span><div>Pierwszy punkt: środek górnej śruby sterów.</div></div><div class="step"><span class="n">2</span><div>Drugi punkt: środek obejmy kierownicy.</div></div><div class="step"><span class="n">3</span><div>Mierz prostą odległość pomiędzy osiami.</div></div></div></div></section>
    <script>const tabs=[['handlebar','Punkt chwytu'],['saddle','S75 na siodle'],['bb','Środek suportu'],['saddleheight','Wysokość siodła'],['stem','Mostek']];const nav=document.getElementById('nav');tabs.forEach((t,i)=>{{const b=document.createElement('button');b.textContent=t[1];b.className=i===0?'active':'';b.onclick=()=>{{document.querySelectorAll('.card').forEach(c=>c.classList.toggle('active',c.dataset.id===t[0]));nav.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}};nav.appendChild(b)}});</script></body></html>'''
